import {
  BaseSheet,
  InsertColOperation,
  InsertRowOperation,
  Operation,
  RemoveColOperation,
  RemoveRowOperation,
  Sheet,
  UpdateCellOperation,
  UpdateDimensionOperation,
  ScatterDimensionOperation,
} from '@bzl/sheet-js';
import { initialDoc } from '../utils';
import { SheetOTType } from '../../src';
import { describe, expect, beforeEach, test, afterEach } from 'vitest';

const start = 7;
const end = 9;
const examples = [
  {
    type: 'col',
    op: {
      type: 'scatter-dimension',
      id: '1',
      cols: [
        {
          index: start,
          meta: {
            size: 100,
            hidden: true,
          },
        },
        {
          index: end,
          meta: {
            size: 100,
            hidden: true,
          },
        },
      ],
    } as ScatterDimensionOperation,
  },
  {
    type: 'row',
    op: {
      type: 'scatter-dimension',
      id: '1',
      rows: [
        {
          index: start,
          meta: {
            size: 100,
            hidden: true,
          },
        },
        {
          index: end,
          meta: {
            size: 100,
            hidden: true,
          },
        },
      ],
    } as ScatterDimensionOperation,
  },
];

describe.each(examples)('left side to scatter-dimension ($type), right side to:', ({ op }) => {
  let doc1: Omit<BaseSheet, 'apply'>;
  let doc2: Omit<BaseSheet, 'apply'>;
  const op1: ScatterDimensionOperation = op;
  let op2: Operation;

  beforeEach(() => {
    doc1 = initialDoc() as Sheet;
    doc2 = initialDoc() as Sheet;
  });

  afterEach(() => {
    console.log('op1,', JSON.stringify(op1));
    console.log('op2,', JSON.stringify(op2));
    const [op12, op21] = SheetOTType.xTransformMxN([op1], [op2], 'left');
    console.log('op12,', JSON.stringify(op12), JSON.stringify(op1));
    console.log('op21,', JSON.stringify(op21));
    doc1 = SheetOTType.apply({} as BaseSheet, op1) as BaseSheet;
    console.log('doc1>>>>', JSON.stringify(doc1));
    doc1 = SheetOTType.apply(doc1, op21);
    doc2 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op2) as BaseSheet, op12);
    console.log('doc1,', JSON.stringify(doc1));
    console.log('doc2,', JSON.stringify(doc2));
    expect(doc1).toStrictEqual(doc2);
  });

  describe.each([{ isRow: false }, { isRow: true }])('update-dimension', ({ isRow }) => {
    test(`intersection (${isRow ? 'row' : 'col'})`, () => {
      op2 = {
        type: 'update-dimension',
        meta: {
          size: 500,
        },
        section: {
          from: start,
          to: end - 1,
          isRow,
        },
        id: '1',
      } as UpdateDimensionOperation;
    });
    test(`contain (${isRow ? 'row' : 'col'}) `, () => {
      op2 = {
        type: 'update-dimension',
        meta: {
          size: 500,
        },
        section: {
          from: start - 1,
          to: end + 1,
          isRow,
        },
        id: '1',
      } as UpdateDimensionOperation;
    });
    test(`not intersection (${isRow ? 'row' : 'col'})`, () => {
      op2 = {
        type: 'update-dimension',
        meta: {
          size: 500,
        },
        section: {
          from: start - 3,
          to: start - 1,
          isRow,
        },
        id: '1',
      } as UpdateDimensionOperation;
    });
  });

  describe('update-cell', () => {
    test('at before', () => {
      op2 = {
        type: 'update-cell',
        at: [0, start - 1],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'update-cell',
        at: [0, start + 1],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'update-cell',
        at: [0, start],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
    });
  });

  describe('insert-col', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-col',
        at: start - 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-col',
        at: end + 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'insert-col',
        at: start,
        count: 3,
        id: '1',
      } as InsertColOperation;
    });
    test('at inner', () => {
      op2 = {
        type: 'insert-col',
        at: start + 1,
        count: 3,
        id: '1',
      } as InsertColOperation;
    });
  });

  describe('insert-row', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-row',
        at: start - 1,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-row',
        at: end + 1,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'insert-row',
        at: start,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
  });

  describe('remove-col', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-col',
        at: start - 3,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-col',
        at: end + 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test.only('intersection before', () => {
      op2 = {
        type: 'remove-col',
        at: start - 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('intersection after', () => {
      op2 = {
        type: 'remove-col',
        at: end - 1,
        count: 4,
        id: '1',
      } as RemoveColOperation;
    });
    test('cover', () => {
      op2 = {
        type: 'remove-col',
        at: start - 1,
        count: end + 1,
        id: '1',
      } as RemoveColOperation;
    });
    test('contain', () => {
      op2 = {
        type: 'remove-col',
        at: start,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
  });

  describe('remove-row', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-row',
        at: start - 3,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-row',
        at: end + 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('intersection before', () => {
      op2 = {
        type: 'remove-row',
        at: start - 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('intersection after', () => {
      op2 = {
        type: 'remove-row',
        at: end - 1,
        count: 4,
        id: '1',
      } as RemoveRowOperation;
    });
    test('cover', () => {
      op2 = {
        type: 'remove-row',
        at: start - 1,
        count: end + 1,
        id: '1',
      } as RemoveRowOperation;
    });
    test('contain', () => {
      op2 = {
        type: 'remove-row',
        at: start,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
  });
});
